type mediaProcessor struct{}

func NewMediaProcessor\(\) IMediaProcessor {
	return &mediaProcessor{}
}

func \(p *mediaProcessor\) ProcessImage\(ctx context.Context, media *models.MediaFile\) error {
	width, height, err := p.GetImageDimensions\(media.FilePath\)
	if err != nil {
		utils.Warn\("Failed to get image dimensions", map[string]interface{}{
			"file_id": media.ID.Hex\(\),
			"path":    media.FilePath,
			"error":   err.Error\(\),
		}\)
	} else {
		media.Width = width
		media.Height = height
		media.AspectRatio = calculateAspectRatio\(width, height\)
	}

	if media.FileType == models.MediaFileTypeImage {
		thumbnailPath := p.getThumbnailPath\(media.FilePath\)
		err := p.CreateThumbnail\(media.FilePath, thumbnailPath, config.Media.ThumbnailWidth, config.Media.ThumbnailHeight\)
		if err != nil {
			utils.Warn\("Failed to create thumbnail", map[string]interface{}{
				"file_id": media.ID.Hex\(\),
				"error":   err.Error\(\),
			}\)
		} else {
			thumbnailName := filepath.Base\(thumbnailPath\)
			media.ThumbnailURL = fmt.Sprintf\("/uploads/thumbnails/%s", thumbnailName\)
		}
	}

	media.MarkAsReady\(\)
	return nil
}

func \(p *mediaProcessor\) ProcessVideo\(ctx context.Context, media *models.MediaFile\) error {
	if !p.isFFmpegAvailable\(\) {
		utils.Warn\("ffmpeg/ffprobe not available, skipping video processing", map[string]interface{}{
			"file_id": media.ID.Hex\(\),
		}\)
		media.MarkAsReady\(\)
		return nil
	}

	utils.Info\("Processing video", map[string]interface{}{
		"file_id": media.ID.Hex\(\),
		"path":    media.FilePath,
	}\)

	duration, err := p.GetVideoDuration\(media.FilePath\)
	if err != nil {
		utils.Warn\("Failed to get video duration", map[string]interface{}{
			"file_id": media.ID.Hex\(\),
			"error":   err.Error\(\),
		}\)
	} else {
		media.Duration = duration
	}

	width, height, err := p.getVideoDimensions\(media.FilePath\)
	if err != nil {
		utils.Warn\("Failed to get video dimensions", map[string]interface{}{
			"file_id": media.ID.Hex\(\),
			"error":   err.Error\(\),
		}\)
	} else {
		media.Width = width
		media.Height = height
		media.AspectRatio = calculateAspectRatio\(width, height\)
	}

	thumbnailPath := p.getVideoThumbnailPath\(media.FilePath\)
	seekTime := 1
	if duration > 0 && duration < 1 {
		seekTime = 0
	}
	err = p.ExtractVideoThumbnail\(media.FilePath, thumbnailPath, seekTime\)
	if err != nil {
		utils.Warn\("Failed to extract video thumbnail", map[string]interface{}{
			"file_id": media.ID.Hex\(\),
			"error":   err.Error\(\),
		}\)
	} else {
		thumbnailName := filepath.Base\(thumbnailPath\)
		media.ThumbnailURL = fmt.Sprintf\("/uploads/thumbnails/%s", thumbnailName\)
	}

	media.MarkAsReady\(\)
	return nil
}

func \(p *mediaProcessor\) CreateThumbnail\(sourcePath, destPath string, maxWidth, maxHeight int\) error {
	srcImage, err := imaging.Open\(sourcePath\)
	if err != nil {
		return fmt.Errorf\("failed to open source image: %w", err\)
	}

	thumbnail := imaging.Fit\(srcImage, maxWidth, maxHeight, imaging.Lanczos\)

	destDir := filepath.Dir\(destPath\)
	if err := os.MkdirAll\(destDir, 0755\); err != nil {
		return fmt.Errorf\("failed to create thumbnail directory: %w", err\)
	}

	err = imaging.Save\(thumbnail, destPath, imaging.JPEGQuality\(85\)\)
	if err != nil {
		return fmt.Errorf\("failed to save thumbnail: %w", err\)
	}

	return nil
}

func \(p *mediaProcessor\) ResizeImage\(sourcePath, destPath string, maxWidth, maxHeight int\) error {
	srcImage, err := imaging.Open\(sourcePath\)
	if err != nil {
		return fmt.Errorf\("failed to open source image: %w", err\)
	}

	resized := imaging.Fit\(srcImage, maxWidth, maxHeight, imaging.Lanczos\)

	destDir := filepath.Dir\(destPath\)
	if err := os.MkdirAll\(destDir, 0755\); err != nil {
		return fmt.Errorf\("failed to create destination directory: %w", err\)
	}

	err = imaging.Save\(resized, destPath, imaging.JPEGQuality\(90\)\)
	if err != nil {
		return fmt.Errorf\("failed to save resized image: %w", err\)
	}

	return nil
}

func \(p *mediaProcessor\) GetImageDimensions\(filePath string\) \(width, height int, err error\) {
	file, err := os.Open\(filePath\)
	if err != nil {
		return 0, 0, fmt.Errorf\("failed to open file: %w", err\)
	}
	defer file.Close\(\)

	imgConfig, _, err := image.DecodeConfig\(file\)
	if err != nil {
		return 0, 0, fmt.Errorf\("failed to decode image config: %w", err\)
	}

	return imgConfig.Width, imgConfig.Height, nil
}

func \(p *mediaProcessor\) GetVideoDuration\(filePath string\) \(int, error\) {
	cmd := exec.Command\("ffprobe",
		"-v", "error",
		"-show_entries", "format=duration",
		"-of", "default=noprint_wrappers=1:nokey=1",
		filePath,
	\)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run\(\); err != nil {
		return 0, fmt.Errorf\("ffprobe failed: %w - %s", err, stderr.String\(\)\)
	}

	durationStr := strings.TrimSpace\(stdout.String\(\)\)
	if durationStr == "" || durationStr == "N/A" {
		return 0, nil
	}

	duration, err := strconv.ParseFloat\(durationStr, 64\)
	if err != nil {
		return 0, fmt.Errorf\("failed to parse duration: %w", err\)
	}

	return int\(duration\), nil
}

func \(p *mediaProcessor\) ExtractVideoThumbnail\(videoPath, thumbnailPath string, seekSeconds int\) error {
	destDir := filepath.Dir\(thumbnailPath\)
	if err := os.MkdirAll\(destDir, 0755\); err != nil {
		return fmt.Errorf\("failed to create thumbnail directory: %w", err\)
	}

	cmd := exec.Command\("ffmpeg",
		"-ss", fmt.Sprintf\("%d", seekSeconds\),
		"-i", videoPath,
		"-vframes", "1",
		"-q:v", "2",
		"-y",
		thumbnailPath,
	\)

	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	if err := cmd.Run\(\); err != nil {
		return fmt.Errorf\("ffmpeg failed: %w - %s", err, stderr.String\(\)\)
	}

	if _, err := os.Stat\(thumbnailPath\); os.IsNotExist\(err\) {
		return fmt.Errorf\("thumbnail was not created"\)
	}

	return nil
}

func \(p *mediaProcessor\) getVideoDimensions\(filePath string\) \(width, height int, err error\) {
	cmd := exec.Command\("ffprobe",
		"-v", "error",
		"-select_streams", "v:0",
		"-show_entries", "stream=width,height",
		"-of", "csv=p=0:s=x",
		filePath,
	\)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run\(\); err != nil {
		return 0, 0, fmt.Errorf\("ffprobe failed: %w - %s", err, stderr.String\(\)\)
	}

	output := strings.TrimSpace\(stdout.String\(\)\)
	if output == "" {
		return 0, 0, fmt.Errorf\("no video stream found"\)
	}

	parts := strings.Split\(output, "x"\)
	if len\(parts\) != 2 {
		return 0, 0, fmt.Errorf\("unexpected ffprobe output: %s", output\)
	}

	width, err = strconv.Atoi\(strings.TrimSpace\(parts[0]\)\)
	if err != nil {
		return 0, 0, fmt.Errorf\("failed to parse width: %w", err\)
	}

	height, err = strconv.Atoi\(strings.TrimSpace\(parts[1]\)\)
	if err != nil {
		return 0, 0, fmt.Errorf\("failed to parse height: %w", err\)
	}

	return width, height, nil
}

func \(p *mediaProcessor\) isFFmpegAvailable\(\) bool {
	_, err := exec.LookPath\("ffprobe"\)
	if err != nil {
		return false
	}
	_, err = exec.LookPath\("ffmpeg"\)
	return err == nil
}

func \(p *mediaProcessor\) getThumbnailPath\(sourcePath string\) string {
	filename := filepath.Base\(sourcePath\)
	ext := filepath.Ext\(filename\)
	name := filename[:len\(filename\)-len\(ext\)]
	thumbnailName := fmt.Sprintf\("%s_thumb.jpg", name\)
	return filepath.Join\(config.Media.ThumbnailDir, thumbnailName\)
}

func \(p *mediaProcessor\) getVideoThumbnailPath\(videoPath string\) string {
	filename := filepath.Base\(videoPath\)
	ext := filepath.Ext\(filename\)
	name := filename[:len\(filename\)-len\(ext\)]
	thumbnailName := fmt.Sprintf\("%s_thumb.jpg", name\)
	return filepath.Join\(config.Media.ThumbnailDir, thumbnailName\)
}

func calculateAspectRatio\(width, height int\) string {
	if width == 0 || height == 0 {
		return ""
	}

	gcd := gcdFunc\(width, height\)
	return fmt.Sprintf\("%d:%d", width/gcd, height/gcd\)
}

func gcdFunc\(a, b int\) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
